def process_batch(batch):
    directory = batch.get('directory') or {}
    if not isinstance(directory, dict):
        directory = {}
    accounts = batch.get('accounts') or {}
    if not isinstance(accounts, dict):
        accounts = {}
    gateways = batch.get('gateways') or {}
    if not isinstance(gateways, dict):
        gateways = {}
    jobs = batch.get('jobs')
    if not isinstance(jobs, list):
        jobs = []

    aliases, domains = build_directory(directory)
    results = []
    wires = []
    for index, job in enumerate(jobs):
        if not isinstance(job, dict):
            result = {'status': 'reject', 'reason': UPSTREAM}
        else:
            try:
                result = process_job(job, index, jobs, wires, aliases, domains,
                                     accounts, gateways)
            except Reject as exc:
                result = {'status': 'reject', 'reason': exc.reason}
            except Exception:
                # A single malformed job must never fail the whole batch.
                result = {'status': 'reject', 'reason': SYNTAX}
        if result.get('status') == 'accept':
            wires.append(result['wire'])
        else:
            wires.append(None)
        results.append(result)
    return {'results': results}


def main():
    data = sys.stdin.buffer.read()
    batch = json.loads(data.decode('utf-8-sig'))
    if not isinstance(batch, dict):
        raise ValueError('batch must be a JSON object')
    output = process_batch(batch)
    sys.stdout.write(json.dumps(output))
    sys.stdout.write('\n')
    sys.stdout.flush()
    return 0


if __name__ == '__main__':
    try:
        code = main()
    except Reject as exc:
        sys.stderr.write('reject: %s\n' % exc.reason)
        code = 1
    sys.exit(code)
